@startuml

class Gym {
  + MonthlyIncome(d : date) : int
  + AnnualIncome(d : date) : int
  + PrintDefaulters()
  + PrintDueChecks()
}

class Customer {
  + name : string
  + surname : string
  + age : int
  + address : string
  + profession : string
}

class Subscription {
  + startDate : date
}

class MonthlySubscription extends Subscription {
}

class AnnualSubscription extends Subscription {
}

class Service {
  + name : string
  + additionalCost : int
}

class BaseService {
}

class AdditionalService {
}

class WorkoutPlan {
  + weeklyVisits : int
}

class Exercise {
  + description : string
}

class WorkoutPlanExercise {
  + number : int
  + frequency : string
}

class MedicalStaff {
}

class MedicalCheck {
  + weight : float
  + bodyFat : float
  + electrocardiogram : string
  + restingHeartbeat : int
  + stressHeartbeat : int
}

class Diet {
}

Customer "1" -- "1" Subscription
Customer "1" -- "0..1" WorkoutPlan
Customer "0..*" -- "0..*" Service
Customer "0..*" -- "0..1" MedicalStaff : requests service
MedicalStaff "1" -- "0..*" MedicalCheck
MedicalStaff "1" -- "0..*" Diet
WorkoutPlan "1" -- "1..*" WorkoutPlanExercise
WorkoutPlanExercise "0..*" -- "1" Exercise
Gym "1" -- "0..*" Subscription
Gym "1" -- "0..*" Service
Gym "1" -- "0..*" MedicalStaff

@enduml

